def custom_encode_2(val: int) -> np.ndarray:
    if val == 0:
        return np.array([0, 0], dtype=np.float32)
    elif val == 1:
        return np.array([0, 1], dtype=np.float32)
    elif val == 2:
        return np.array([1, 0], dtype=np.float32)
    else:
        raise ValueError("Value must be 0, 1, or 2.")

def custom_encode_status(val: int) -> np.ndarray:
    if val == 0:
        return np.array([0, 0, 0], dtype=np.float32)
    elif val == 1:
        return np.array([0, 0, 1], dtype=np.float32)
    elif val == 2:
        return np.array([0, 1, 0], dtype=np.float32)
    elif val == 3:
        return np.array([1, 0, 0], dtype=np.float32)
    else:
        raise ValueError("Local board status must be 0, 1, 2, or 3.")

def custom_encode_coord(val: int) -> np.ndarray:
    if val < 0:
        return np.array([0, 0], dtype=np.float32)
    return custom_encode_2(val)


class LocalBoardEncoder(nn.Module):
    """Encodes a single 3x3 local board (18 features after one-hot) into a compact representation."""
    def __init__(self, input_dim=18, hidden_dim=32, output_dim=8):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(input_dim, hidden_dim),
            nn.ReLU(),
            nn.Linear(hidden_dim, output_dim),
            nn.ReLU()
        )
    
    def forward(self, x):
        # x: (batch, 18) - one local board's 9 cells × 2 features each
        return self.net(x)  # (batch, 16)


class GlobalBoardEncoder(nn.Module):
    """Processes the 9 local board encodings + local board statuses to understand meta-game."""
    def __init__(self, local_encoding_dim=8, status_dim=27, hidden_dim=128, output_dim=64):
        super().__init__()
        # Input: 9 local encodings (9 × 8 = 72) + 9 local statuses (27) = 99
        input_dim = 9 * local_encoding_dim + status_dim
        self.net = nn.Sequential(
            nn.Linear(input_dim, hidden_dim),
            nn.BatchNorm1d(hidden_dim),
            nn.ReLU(),
            nn.Dropout(0.2),
            nn.Linear(hidden_dim, output_dim),
            nn.ReLU()
        )
    
    def forward(self, local_encodings, local_status):
        # local_encodings: (batch, 9, 16)
        # local_status: (batch, 27)
        batch_size = local_encodings.shape[0]
        flat_encodings = local_encodings.view(batch_size, -1)  # (batch, 144)
        combined = torch.cat([flat_encodings, local_status], dim=1)  # (batch, 171)
        return self.net(combined)  # (batch, 64)


class HierarchicalNet(nn.Module):
    """
    Hierarchical model that mirrors Ultimate TTT structure:
    1. LocalBoardEncoder processes each 3x3 local board separately (shared weights)
    2. GlobalBoardEncoder combines all local encodings + meta-board status
    3. Context encoder handles whose turn + where must play
    4. Value head outputs final position evaluation
    """
    def __init__(self):
        super().__init__()
        
        # Shared local board encoder (processes each of 9 local boards)
        self.local_encoder = LocalBoardEncoder(input_dim=18, hidden_dim=32, output_dim=16)
        
        # Global encoder for meta-board strategy
        self.global_encoder = GlobalBoardEncoder(local_encoding_dim=16, status_dim=27, hidden_dim=128, output_dim=64)
        
        # Context: fill_num (2) + prev_local_action (4) = 6 features
        self.context_encoder = nn.Sequential(
            nn.Linear(6, 16),
            nn.ReLU()
        )
        
        # Value head: combines global understanding + context
        self.value_head = nn.Sequential(
            nn.Linear(64 + 16, 32),
            nn.ReLU(),
            nn.Dropout(0.1),
            nn.Linear(32, 1)
        )
    
    def forward(self, x):
        """
        x: (batch, 195) feature vector with layout:
           - [0:162]   = global board (81 cells × 2 features) - but organized as 9 local boards
           - [162:189] = local board status (9 × 3 features)
           - [189:191] = fill_num (2 features)
           - [191:195] = prev_local_action (4 features)
        """
        batch_size = x.shape[0]
        
        # Split features
        global_board = x[:, :162]      # (batch, 162)
        local_status = x[:, 162:189]   # (batch, 27)
        context = x[:, 189:195]        # (batch, 6) - fill_num + prev_action
        
        # Reshape global board to (batch, 9, 18) - 9 local boards, each with 9 cells × 2 features
        # Note: Your encoding flattens board as (3,3,3,3) -> 81 cells -> 162 features
        # We need to extract each local board's 9 cells (18 features)
        local_boards = global_board.view(batch_size, 9, 18)  # (batch, 9, 18)
        
        # Encode each local board using shared encoder
        local_encodings = []
        for i in range(9):
            enc = self.local_encoder(local_boards[:, i, :])  # (batch, 16)
            local_encodings.append(enc)
        local_encodings = torch.stack(local_encodings, dim=1)  # (batch, 9, 16)
        
        # Global encoding
        global_enc = self.global_encoder(local_encodings, local_status)  # (batch, 64)
        
        # Context encoding
        context_enc = self.context_encoder(context)  # (batch, 16)
        
        # Final value
        combined = torch.cat([global_enc, context_enc], dim=1)  # (batch, 80)
        value = self.value_head(combined)  # (batch, 1)
        
        return value


class StudentAgent7:
    def __init__(self, depth: int = 3):
        self.depth = depth
        self.device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
        self.model = HierarchicalNet().to(self.device)
        self.model.eval()

    def extract_features(self, state: State) -> np.ndarray:
        board_flat = state.board.reshape(-1) 
        global_board_features = np.array([custom_encode_2(val) for val in board_flat]).flatten()
        
        local_board_flat = state.local_board_status.reshape(-1)  
        local_board_features = np.array([custom_encode_status(val) for val in local_board_flat]).flatten()
  
        fill_num_feature = custom_encode_2(state.fill_num)
        
        if state.prev_local_action is None:
            prev_r, prev_c = -1, -1
        else:
            prev_r, prev_c = state.prev_local_action
        prev_r_enc = custom_encode_coord(prev_r)
        prev_c_enc = custom_encode_coord(prev_c) 
        prev_action = np.concatenate([prev_r_enc, prev_c_enc])
        
        features = np.concatenate([global_board_features, local_board_features, fill_num_feature, prev_action])
        return features

    def evaluate(self, state: State) -> float:
        if state.is_terminal():
            util = state.terminal_utility()
            return 1 if util == 1.0 else -1 if util == 0.0 else 0

        features = self.extract_features(state)
        features_tensor = torch.tensor(features, dtype=torch.float32).to(self.device).unsqueeze(0)
        score = self.model(features_tensor).item()
        return score

    def minimax(
        self,
        state: State,
        depth: int,
        is_max: bool,
        alpha: float,
        beta: float
    ) -> tuple[float | None, Action | None]:
        if time.time() - self.search_start_time >= self.search_time_limit * 0.95:
            return None, None

        if depth == 0 or state.is_terminal():
            return self.evaluate(state), None

        valid_actions = state.get_all_valid_actions()
        best_action = None

        if is_max:
            max_eval = -float('inf')
            for action in valid_actions:
                new_state = state.change_state(action)
                eval_score, _ = self.minimax(new_state, depth - 1, False, alpha, beta)
                if eval_score is None:
                    return None, None
                if eval_score > max_eval:
                    max_eval = eval_score
                    best_action = action
                alpha = max(alpha, eval_score)
                if beta <= alpha:
                    break
            return max_eval, best_action
        else:
            min_eval = float('inf')
            for action in valid_actions:
                new_state = state.change_state(action)
                eval_score, _ = self.minimax(new_state, depth - 1, True, alpha, beta)
                if eval_score is None:
                    return None, None
                if eval_score < min_eval:
                    min_eval = eval_score
                    best_action = action
                beta = min(beta, eval_score)
                if beta <= alpha:
                    break
            return min_eval, best_action

    def choose_action(self, state: State) -> Action:
        self.search_time_limit = 2.9
        self.search_start_time = time.time()
        best_action = None
        current_depth = 3
        is_max = True if state.fill_num == 1 else False
        while time.time() - self.search_start_time < self.search_time_limit:
            result = self.minimax(state, current_depth, is_max, -float('inf'), float('inf'))
            if result[0] is None:
                break
            score, action = result
            if action is not None:
                best_action = action
            current_depth += 1

        return best_action if best_action is not None else state.get_random_valid_action()
